import * as G from './engine.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='crown-calamity-v1';let saveOK=true,saveRaw=null;try{saveRaw=localStorage.getItem(KEY);}catch{saveOK=false;}
let state=G.loadSave(saveRaw)||G.fresh(),view='hunt',huntTab='hunts',bagTab='gear',charTab='overview',toastTimer,actionDelayTimer;
const icons={crown:'<path d="m3 7 5 5 4-8 4 8 5-5-2 13H5z"/><path d="M7 23h10M9 16l3-4 3 4"/>',hunt:'<path d="m5 3 14 18M19 3 5 21M3 5l4-2 1 4M21 5l-4-2-1 4M3 18l5 3M21 18l-5 3"/>',character:'<path d="M5 4h14v17H5zM9 8h6M9 12h6M9 16h4"/>',bag:'<path d="M7 9 4 20h16L17 9zM8 9V5h8v4M9 14h6"/>',journal:'<path d="M4 4h6l2 2 2-2h6v16h-6l-2 2-2-2H4zM12 6v16M7 9h2M15 9h2M7 13h2M15 13h2"/>',guide:'<circle cx="12" cy="12" r="9"/><path d="M9 8c1-3 6-2 6 1 0 2-3 2-3 4M12 17h.01"/>',pin:'<path d="M18 9c0 5-6 12-6 12S6 14 6 9a6 6 0 1 1 12 0Z"/><circle cx="12" cy="9" r="2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',coin:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="5"/><path d="M12 9v6M10 10h3M11 14h3"/>',heart:'<path d="M20 5c-2-2-6-1-8 2-2-3-6-4-8-2-5 5 8 15 8 15S25 10 20 5Z"/>',mana:'<path d="m12 2 7 10-7 10-7-10zM5 12h14M12 2v20"/>',bolt:'<path d="m14 2-9 12h7l-2 8 9-12h-7z"/>',shield:'<path d="m12 3 8 3v7c0 5-8 9-8 9s-8-4-8-9V6zM12 7v10M8 12h8"/>',sword:'<path d="m5 20 3-3M3 18l5 5M7 17 19 3h3v3L10 20M5 15l7 7"/>',staff:'<path d="m6 22 9-15M14 7l-3-3 4-3 5 3-2 4z"/>',coat:'<path d="m8 3-6 5 3 5 2-1v9h10v-9l2 1 3-5-6-5-4 4z"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>',rest:'<path d="M3 14h18v7M3 9v12M3 16h18M6 14v-4h5v4M11 12h10v2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',check:'<path d="m5 12 4 4L20 5"/>',leaf:'<path d="M5 20 19 5M5 15C1 3 13 2 21 3c0 11-4 17-13 14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',scroll:'<path d="M6 3h12v14M6 3a3 3 0 0 0-3 3h12M6 6v14h13a3 3 0 0 0 0-6h-1M9 10h6M9 14h4"/>',exit:'<path d="M10 3H4v18h6M9 12h12m-5-5 5 5-5 5"/>',cross:'<path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>'};
function icon(k,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 26" aria-hidden="true">${icons[k]||icons.spark}</svg>`;}
const ENEMY_FRAMES={rats:{x:0,y:0,w:430,h:429},scavenger:{x:448,y:0,w:430,h:429},wisp:{x:897,y:0,w:430,h:429},crab:{x:1346,y:0,w:428,h:429},inspector:{x:0,y:446,w:430,h:441},hound:{x:448,y:446,w:430,h:441},boss:{x:897,y:446,w:430,h:441}};
function enemyArt(e){const id=e.art==='rat'?'rats':e.art,f=ENEMY_FRAMES[id]||ENEMY_FRAMES.rats;return `<div class="enemy-token ${esc(id)}"><img src="assets/enemies/enemy-atlas.png" alt="${esc(e.name)}" loading="lazy" style="width:${1774/f.w*100}%;height:${887/f.h*100}%;left:${-f.x/f.w*100}%;top:${-f.y/f.h*100}%"></div>`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveOK=true;}catch{saveOK=false;}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function btn(action,text,cls='',disabled=false){return `<button data-action="${esc(action)}" class="${cls}" ${disabled?'disabled':''}>${text}</button>`;}
function resolved(id){return G.resolveItem(state,id);}
function itemIcon(i){return ({weapon:i.focus?'staff':'sword',offhand:i.armor?'shield':'spark',head:'crown',body:'coat',hands:'shield',feet:'rest',accessory:'spark',accessory2:'spark',relic:'scroll'})[i.slot]||'spark';}
function nav(){return [['hunt','The adventure','hunt'],['character','Character','character'],['bag','Satchel','bag'],['journal','Chronicle','journal'],['guide','Field guide','guide']];}
function resources(){const t=G.totals(state);return `<div class="resources" aria-label="Character resources">${[['hp','Health','heart'],['mp','Mana','mana'],['sp','Stamina','bolt']].map(([k,label,ic])=>`<div class="resource ${k}"><label><span class="resource-name">${icon(ic)} ${label.toUpperCase()}</span><span class="${k==='hp'&&state.hp<t.hp*.25?'health-warning':''}">${state[k]} <span class="muted">/ ${t[k]}</span></span></label><div class="bar" role="meter" aria-label="${label}" aria-valuemin="0" aria-valuemax="${t[k]}" aria-valuenow="${state[k]}"><i style="width:${Math.max(0,state[k]/t[k]*100)}%"></i></div></div>`).join('')}${btn('rest',`${icon('rest')} Recover`,'resource-rest',!!state.fight||!!state.delve)}</div>`;}
function shell(body,title,subtitle,eyebrow='CHAPTER I · BRACKEN QUAY'){const combat=!!state.fight&&view==='hunt';return `<div class="shell"><aside class="sidebar"><div class="brand">${icon('crown')}<div class="wordmark">CROWN <span>&</span> CALAMITY</div></div><div class="nav-label">YOUR ADVENTURE</div><nav aria-label="Main navigation">${nav().map(([v,n,i])=>btn('nav:'+v,`${icon(i)}${n}${v==='character'&&state.points?`<span class="count">${state.points}</span>`:''}`,`nav-link ${view===v?'active':''}`)).join('')}</nav><div class="sidebar-footer"><div class="location">${icon('pin')} Bracken Quay</div><p>The water is rising.<br>The paperwork is not helping.</p>${btn('rest',`${icon('rest')} Rest at the Quay`,'subtle',!!state.fight||!!state.delve)}<div class="version">SOLO PROTOTYPE · v0.3.0</div></div></aside><div class="page ${combat?'in-combat':''}"><header class="topbar"><div class="top-mobile-brand">${icon('crown')} Crown & Calamity</div><div class="place">${icon('pin')} <span>Bracken Quay</span> <span>/</span><span>${{hunt:'The Lower Canals',character:'Character record',bag:'Personal effects',journal:'Adventure chronicle',guide:'Field guide'}[view]}</span></div><div class="topbar-right"><span class="save-label"><i class="save-dot"></i>${saveOK?'Saved on this browser':'Saving unavailable'}</span><span class="coins">${icon('coin')} ${state.coins.toLocaleString()}</span><button data-action="nav:character" class="identity-button" aria-label="Open character sheet"><span class="identity-name">${esc(state.name)}</span><span class="level-box" title="Level ${state.level}">${state.level}</span></button></div></header><main class="content" id="main"><div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><span class="chapter-seal"><i></i> A PROVISIONAL ADVENTURER</span></div>${!saveOK?'<div class="error-banner">Browser saving is unavailable. Export a save from the Field Guide to keep your progress.</div>':''}${state.fight&&view!=='hunt'?`<div class="point-notice">An encounter is in progress. ${btn('nav:hunt','Return to encounter →')}</div>`:''}${resources()}${body}</main><footer class="footer"><span>CROWN & CALAMITY <span class="muted">/</span> AN ORIGINAL LITRPG</span><span>No waiting. No offline gains. Just your next move.</span></footer></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav().map(([v,n,i])=>btn('nav:'+v,`${icon(i)}<span>${{hunt:'Adventure',character:'Character',bag:'Satchel',journal:'Chronicle',guide:'Guide'}[v]}</span>${v==='character'&&state.points?'<span class="badge">!</span>':''}`,view===v?'active':'')).join('')}</nav></div>`;}
function titlePanel(label,body,cls=''){return `<section class="panel ${cls}"><div class="panel-label">${label}</div>${body}</section>`;}
function questPanel(){const q=G.QUESTS[state.quest];if(!q)return titlePanel(`CHAPTER COMPLETE ${icon('check')}`,`<h3>The city stays dry.</h3><p>The works are safe. Your crew is coming home. Hunt, experiment with your build, or make another descent.</p><div class="quest-goal">Below the Waterline · completed</div>`,'quest-panel');return titlePanel(`CURRENT CONTRACT ${icon('scroll')}`,`<div class="quest-step">0${state.quest+1} <span>— BELOW THE WATERLINE</span></div><h3>${q.title}</h3><p>${q.text}</p><div class="quest-goal">${state.pending!==null?'Ready to turn in':`Defeat ${G.ENEMIES.find(e=>e.id===q.target).name}`}</div><div class="quest-reward"><span>${icon('spark')} ${q.xp} XP</span><span>${icon('coin')} Choice of reward</span></div>${state.pending!==null?btn('claim','Review outcome →','text-button full-width'):''}`,'quest-panel');}
const SLOT_ORDER=['weapon','offhand','head','body','hands','feet','accessory','accessory2','relic'];
const SLOT_LABELS={weapon:'Weapon',offhand:'Offhand',head:'Head',body:'Body',hands:'Hands',feet:'Feet',accessory:'Accessory',accessory2:'Second accessory',relic:'Relic'};
function equippedSlots(){return SLOT_ORDER.map(slot=>{const id=state.gear?.[slot],i=id?resolved(id):null;return `<div class="loadout-item ${i?'':'empty-slot'}"><span class="slot-icon">${icon(i?itemIcon(i):'lock')}</span><div><small>${SLOT_LABELS[slot]}</small><b>${i?esc(i.name):'Empty'}</b>${i?`<small>${itemStats(i).join(' · ')||i.desc}</small>`:''}</div></div>`;}).join('');}
function buildPanel(){const abilityNames=G.ABILITIES||{};const active=(state.equippedAbilities||[]).map(id=>abilityNames[id]?.name||id);return titlePanel(`EQUIPPED BUILD ${btn('nav:character','Edit →','text-button tiny')}`,`<div class="slot-list compact-slots">${equippedSlots()}</div><div class="passive-box"><b>${icon('spark')} ${abilityNames[state.passive]?.name||state.passive||'No passive'}</b>${abilityNames[state.passive]?.desc||''}</div>${active.length?`<div class="equipped-abilities"><strong>Active abilities</strong><p>${active.map(esc).join(' · ')}</p></div>`:''}`,'loadout-panel');}
function rightSide(){return `<aside class="side-column">${questPanel()}${buildPanel()}<section class="panel quote"><span class="quote-mark">“</span><p>The canal is full of opportunities. Most of them have teeth.</p><footer>B.U.R.S.A.R. · ADVENTURER SERVICES</footer></section></aside>`;}
function pointNotice(){return state.points?`<div class="point-notice"><span>${icon('spark')} Level ${state.level} · <strong>${state.points} attribute points</strong> to spend.</span>${btn('nav:character','Shape your build →')}</div>`:'';}
function hub(){const q=G.QUESTS[state.quest];return `<div class="hero"><div class="hero-top"><span class="eyebrow">BRACKEN QUAY · DISTRICT 01</span><span class="region-pill">HUNTING GROUNDS</span></div><div class="eyebrow">WELCOME TO THE LOWER CANALS</div><h2>An honest day’s calamity.</h2><p>The town stays dry. Something below it doesn’t like that arrangement. Take a contract. Make a name. Mind the teeth.</p><div class="hero-footer"><small>${icon('leaf')} Every adventure starts with a small problem.</small>${btn('hunt:rats','Enter the canals →','primary',state.hp<=0)}</div></div><div class="section-row"><h3>Choose your trouble</h3><small>One tap. One exchange.</small></div><div class="hunt-list">${G.ENEMIES.filter(e=>e.id!=='boss').map(e=>{const locked=e.level>state.level+2;return `<button class="hunt-row ${locked?'locked-row':''}" data-action="hunt:${e.id}" ${locked||state.hp<=0?'disabled':''}>${enemyArt(e)}<div class="hunt-info"><div class="hunt-name">${e.name}</div><p>${e.location}${q?.target===e.id?' · Current contract':''}</p><div class="hunt-meta"><span>${e.hp} HP</span><span>${Math.floor((20+12*e.level)*(e.level-state.level<=-6?.25:e.level-state.level<=-3?.6:1))} XP</span><span>${e.coins} coins</span></div></div><span class="hunt-level">${locked?`UNLOCKS LV ${e.level-2}`:`LV ${e.level}`}</span>${icon(locked?'lock':'chevron','hunt-arrow')}</button>`;}).join('')}</div><p class="bottom-note">${icon('shield')} Progress comes from your actions. The canals can wait for you.</p>`;}
function combatView(){const f=state.fight,e=G.ENEMIES.find(x=>x.id===f.enemy),i=G.intent(state),A=G.ABILITIES||{};const secondary=[...(state.equippedAbilities||[]).filter(id=>id!=='arc').map(id=>[id,A[id]?.name||id]),['recover','Recover'],...(e.id==='boss'&&f.hp<e.hp*.65&&!f.vented?[['vent','Vent']]:[]),['withdraw','Withdraw']];const keyIcon={brace:'shield',disrupt:'sword',mend:'cross',driving:'bolt',aegis:'shield',expose:'spark',recover:'rest',vent:'settings',withdraw:'exit'};return `<section class="encounter"><div class="encounter-top"><div><div class="eyebrow">${e.location.toUpperCase()} · EXCHANGE ${f.round+1}</div><h2>${e.name}</h2><p>${e.blurb}</p><div class="encounter-badges"><span>LEVEL ${e.level}</span><span>ARMOR ${e.armor}</span><span>WARD ${e.ward}</span></div></div>${enemyArt(e)}</div><div class="enemy-health"><label><span>ENEMY HEALTH</span><span>${f.hp} / ${e.hp}</span></label><div class="bar" role="meter" aria-label="Enemy health" aria-valuemin="0" aria-valuemax="${e.hp}" aria-valuenow="${f.hp}"><i style="width:${f.hp/e.hp*100}%"></i></div></div><div class="intent ${i.heavy?'heavy':''}">${icon(i.heavy?'bolt':'shield')}<div><strong>${i.name}</strong><small>${i.heavy?'Heavy attack · Guard or Disrupt can help.':'The enemy responds after your action.'} ~${i.damage} raw damage.</small></div>${f.charge?'<span class="hunt-level gold" style="margin-left:auto">RESERVOIR +10%</span>':''}</div></section><div class="combat-controls" aria-label="Combat actions" tabindex="-1"><div class="action-grid">${[['attack','sword','Attack'],['cast','bolt','Cast'],['combo','spark','Wardcast'],['guard','shield','Defend']].map(([k,ic,label])=>{const a=G.actionInfo(state,k);return `<button class="action-btn ${k==='combo'?'preferred':''}" data-action="combat:${k}" ${a.reason?'disabled':''} title="${esc(a.reason||a.desc)}" aria-label="${label}. ${esc(a.reason||a.desc)}">${icon(ic)}<span>${label}</span><small>${a.cost}</small></button>`;}).join('')}</div><div class="secondary-actions">${secondary.map(([k,label])=>{const a=G.actionInfo(state,k);return btn('combat:'+k,`${icon(keyIcon[k]||'spark')}${esc(a.label||label)}${(f.cooldowns[k]||0)>f.round?` · ${f.cooldowns[k]-f.round}`:''}`, '',!!a.reason);}).join('')}</div><div class="combat-timing" role="status" aria-live="polite"><span id="action-ready-text">Ready for your next action</span><span class="action-delay-track" aria-hidden="true"><i></i></span></div><div class="combat-hint">One exchange per tap · 0.65-second action delay · No queued actions</div></div>${report()}`;}
function report(){let all=state.settings.details;return `<section class="report"><div class="panel-label"><span>ENCOUNTER RECORD</span>${btn('toggle-log',all?'Latest only ↑':'Full record ↓','text-button tiny')}</div>${state.log.length?(all?state.log:state.log.slice(0,5)).map(l=>`<div class="report-line ${l.kind}"><span>${esc(l.text)}</span><small>${l.round+1}</small></div>`).join(''):'<p class="report-empty">Choose an action. Your first exchange will appear here.</p>'}${state.fight?`<div class="mechanics">${btn('mechanics','Inspect actions & rules →','text-button tiny')}</div>`:''}</section>`;}
function outcome(){const l=state.last,e=G.ENEMIES.find(x=>x.id===l.enemy),isWin=l.type==='victory';return `<section class="outcome pulse"><div class="eyebrow">${isWin?'ENCOUNTER COMPLETE':l.type==='defeat'?'BACK TO THE QUAY':'A STRATEGIC DEPARTURE'}</div><h2>${isWin?'One problem. Properly filed.':l.type==='defeat'?'Still on the payroll.':'Live to file another day.'}</h2><p class="muted">${isWin?`${e.name} defeated. The canal is a little less crowded.`:l.type==='defeat'?'The recovery house pulled you out. Completed rewards are safe. Rest, adjust your build, and try again.':'You left the encounter. Its provisional rewards were forfeited.'}</p>${isWin?`<div class="reward-grid"><span>+${l.xp} XP</span><span>+${l.coins} coins</span><span>+1 ${l.material}</span>${l.loot?`<span>${resolved(l.loot).name}</span>`:l.salvaged?'<span>+1 Salvaged fitting</span>':''}</div>`:''}${isWin?`<p class="loot-receipt">Equipment roll · ${percent(l.dropChance??.2)} chance · ${l.loot?'Item found':l.salvaged?'Duplicate converted to a fitting':'No equipment this time'}</p>`:''}<div class="outcome-actions">${state.pending!==null?btn('claim','Review contract →','primary'):state.delve?btn('delve-show','Continue the delve →','primary'):isWin?btn('hunt:'+e.id,'Hunt again →','primary'):btn('rest','Recover at the Quay','primary')}${!state.delve?btn('clear-outcome','Choose another hunt','subtle'):''}</div></section>${pointNotice()}${report()}`;}
function delveView(){if(!state.delve)return `<div class="hero"><div class="hero-top"><span class="eyebrow">THE MUNICIPAL WORKS</span><span class="region-pill">SOLO DELVE · LV 6+</span></div><div class="eyebrow">A VOLUNTARY BAD IDEA</div><h2>Someone has to go below.</h2><p>Five checkpoints. One camp. A supervisor with authority issues. Take your prepared build into the flood-control works.</p><div class="hero-footer"><small>Completed room rewards stay yours.</small>${btn('delve-start',state.level<6?'Unlocks at level 6':'Enter the works →','primary',state.level<6||state.hp<=0)}</div></div><section class="panel" style="margin-top:20px"><h3>Know what you’re signing.</h3><p class="muted">Equipment and attributes lock during the delve. You get one full recovery at camp. Every exchange still needs your input. Returning to town ends this run and resets the camp.</p><p class="muted no-margin">The Superintendent unlocks a guaranteed first-clear item choice. The ordinary hunting grounds remain available.</p></section>`;
const d=state.delve;return `<section class="panel"><div class="eyebrow">THE MUNICIPAL WORKS · SOLO EXPEDITION</div><div class="delve-path">${['Gatehouse','Inspection','Chosen route','One camp','Pump chamber'].map((n,j)=>`<div class="delve-node ${j<d.node?'done':j===d.node?'current':''}">${j+1}. ${n}</div>`).join('')}</div>${d.node===0?`<h2>The gatehouse</h2><p class="muted">A Chainback Crab blocks the maintenance entrance. Its clamp winds up slowly. A spell goes through its armor rather nicely.</p>${btn('delve:enter','Clear the gatehouse →','primary')}`:d.node===1?`<h2>Two ways to help.</h2><p class="muted">Mara’s crew is somewhere below. Their records might say where. But the eastern overflow pump is failing, too.</p><div class="choices">${btn('delve:records','<strong>Recover the ledger</strong><small>Face the Siltbound Inspector. Find evidence of the missing crew.</small>','choice')}${btn('delve:overflow','<strong>Secure the pump</strong><small>Face a Floodgate Hound. Protect the homes above the eastern canal.</small>','choice')}</div><p class="tiny muted">Both routes reach the camp and boss. Your choice is recorded in the Chronicle.</p>`:d.node===3?`<h2>A moment above water.</h2><p class="muted">A dry maintenance platform. A kettle. Nothing trying to eat you. You have ${d.campUsed?'used your recovery charge':'one full recovery available'}.</p><div class="outcome-actions">${btn('delve:rest',d.campUsed?'Camp used':'Use camp recovery','subtle',d.campUsed)}${btn('delve:continue','Face the Superintendent →','primary')}</div>`:'<h2>The works are waiting.</h2>'}<p class="mechanics">${btn('delve-leave','Return to town · end this run','text-button')}</p></section>`;}
function huntView(){return shell(`<div class="layout"><div class="main-column">${!state.fight?`<div class="tabs">${btn('tab:hunts',`${icon('hunt')} Hunting grounds`,huntTab==='hunts'?'active':'')}${btn('tab:delve',`${icon('lock')} Municipal Works`,huntTab==='delve'?'active':'')}</div>`:''}${state.fight?combatView():state.last?outcome():`${pointNotice()}${huntTab==='delve'?delveView():hub()}`}</div>${rightSide()}</div>`,'Below the waterline','A small town. An ancient system. A growing list of problems.');}
const percent=v=>(v*100).toFixed(2)+'%';
const STAT_NAMES={heavyPower:'Heavy power',precisionPower:'Precision power',spellPower:'Spell power',physicalAcc:'Physical accuracy',spellAcc:'Spell accuracy',hp:'Max health',mp:'Max mana',sp:'Max stamina',evasion:'Evasion',critChance:'Critical chance',equipmentDropChance:'Equipment drops',mendHealing:'Mend healing'};
function attributeEffect(k){
 const p=G.attributePreview(state,k);
 return p.changes.map(c=>`${STAT_NAMES[c.field]} ${['critChance','equipmentDropChance'].includes(c.field)?percent(c.before):c.before} → ${['critChance','equipmentDropChance'].includes(c.field)?percent(c.after):c.after}`).join(' · ');
}
function buildInspector(){
 const t=G.totals(state),id=state.fight?.enemy||(G.ENEMIES.some(e=>e.id===state.settings.inspectTarget)?state.settings.inspectTarget:G.ENEMIES.filter(e=>e.level<=state.level).at(-1)?.id)||'rats',enemy=G.ENEMIES.find(e=>e.id===id),w=resolved(state.gear.weapon);
 const physicalMitigation=G.mitigation(t.armor,enemy.level),arcaneMitigation=G.mitigation(t.ward,enemy.level),enemySolidHit=G.hitChance(25+4*enemy.level,t.evasion);
 return `<section class="panel stats-inspector"><div class="panel-label">BUILD INSPECTOR · ACTUAL COMBAT RULES</div><h3>Know what your build does.</h3><p class="muted">Your ${w.name} uses <strong>${w.channel==='spell'?'Intellect':w.channel==='precision'?'Finesse':'Might'}</strong> for Attack. Compare a target before spending points or changing equipment.</p><label class="inspect-target" for="inspect-target">Compare against<select id="inspect-target" ${state.fight?'disabled':''}>${G.ENEMIES.map(e=>`<option value="${e.id}" ${e.id===id?'selected':''}>${e.name} · level ${e.level}</option>`).join('')}</select></label><div class="derived-grid">${[['Heavy power',t.heavyPower],['Precision power',t.precisionPower],['Spell power',t.spellPower],['Physical accuracy',t.physicalAcc],['Spell accuracy',t.spellAcc],['Evasion',t.evasion],['Critical chance',percent(t.critChance)],['Critical damage','125%'],['Mend healing',t.mendHealing],['Physical reduction',percent(physicalMitigation)],['Arcane reduction',percent(arcaneMitigation)],['Enemy glancing chance',percent(1-enemySolidHit)]].map(([n,v])=>`<div class="derived-stat"><span>${n}</span><strong>${v}</strong></div>`).join('')}</div><p class="inspector-context">${state.fight?'Current encounter: includes the enemy’s stance, stored charge, and any adaptation.':'Neutral stance: excludes encounter-only Guard, wards, Reservoir charges, and boss openings.'} Reduction and accuracy depend on the selected enemy. Critical chance applies to solid hits.</p><div class="damage-profiles">${[['attack','Attack','Free'],['cast','Arc Bolt','12 mana'],['combo','Wardcast','12 mana · 8 stamina + Guard']].map(([key,label,cost])=>{const a=G.actionProfile(state,key,id);return `<div class="damage-profile"><div class="flex-between"><h4>${label}</h4><span>${a.available?cost:'Requires '+(key==='combo'?'a focus & shield':'a focus')}</span></div><dl><div><dt>Normal / critical / glancing</dt><dd>${a.normal} / ${a.critical} / ${a.glance}</dd></div><div><dt>Solid-hit chance</dt><dd>${percent(a.hitChance)}</dd></div><div><dt>Average per action</dt><dd>${a.average.toFixed(1)} ${a.channel}</dd></div></dl>${!a.available?'<p class="muted">Preview only; this action is unavailable with your equipment.</p>':''}</div>`;}).join('')}</div></section><section class="panel fortune-panel"><div class="panel-label">LUCK · SMALL EDGES, REAL EFFECTS</div><h3>Fortune has rules.</h3><div class="derived-grid"><div class="derived-stat"><span>Total Luck</span><strong>${t.lck}</strong></div><div class="derived-stat"><span>Equipment-drop chance</span><strong>${percent(t.equipmentDropChance)}</strong></div></div><p>Luck above 8 improves critical chance and equipment drops with diminishing returns. A Copper-Thread Charm adds +4 Luck and is available from the Quay outfitter for 25 coins.</p><p class="muted">Guaranteed XP, coins, materials, and first-boss rewards stay guaranteed. Luck never grants extra exchanges or bypasses the action delay. Duplicate equipment drops become salvaged fittings.</p>${btn('shop-luck','Visit the outfitter →','text-button')}</section>`;
}
function tabButton(id,label){return btn('char-tab:'+id,label,charTab===id?'active':'');}
function requirementsView(req,raw={}){if(!req)return '';const rows=[];if(req.level?.required>0)rows.push(`Level ${state.level} / ${req.level.required}`);if(raw.questOrGuards){const needQ=req.quest?.required||raw.quest||0,needG=req.usefulGuards?.required||raw.usefulGuards||0,met=!!(req.quest?.met||req.usefulGuards?.met);if(needQ||needG)rows.push(`${met?'Met · ':''}${needQ} contracts or ${needG} useful Guards`);}else if(req.quest?.required>0)rows.push(`Contracts ${state.quest} / ${req.quest.required}`);if(req.guardCount?.required>0)rows.push(`Useful Guards ${state.guardCount||0} / ${req.guardCount.required}`);if(req.usefulGuards?.required>0&&!raw.questOrGuards)rows.push(`Useful Guards ${state.usefulGuards||0} / ${req.usefulGuards.required}`);return rows.length?`<div class="requirement-list"><strong>Requirements</strong>${rows.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:'';}
function abilityScreen(){
 const A=G.ABILITIES||{},ids=Object.keys(A),active=ids.filter(id=>A[id].kind==='active'),passives=ids.filter(id=>A[id].kind==='passive'),used=G.attunementUsed?G.attunementUsed(state):0,locked=!!state.fight||!!state.delve;
 const card=id=>{const a=A[id],st=G.abilityStatus(state,id)||{},mastery=st.mastery||state.mastery?.[id]||a.mastery||{},passiveOverflow=a.kind==='passive'&&used-(A[state.passive]?.kind==='passive'?A[state.passive].attunement:0)+(a.attunement||0)>6,activeOverflow=a.kind==='active'&&!st.equipped&&used+(a.attunement||0)>6,slotOverflow=a.kind==='active'&&!st.equipped&&(state.equippedAbilities||[]).length>=3,equipBlock=passiveOverflow?'Exceeds the 6-point attunement limit.':activeOverflow?'Exceeds the 6-point attunement limit.':slotOverflow?'All three active slots are occupied.':'';return `<article class="ability-card ${st.equipped?'equipped':''} ${!st.learned?'ability-locked':''}"><div class="ability-card-head"><div><span class="eyebrow">${a.kind==='passive'?'PASSIVE':'ACTIVE'} · ${a.attunement||0} ATTUNEMENT</span><h3>${esc(a.name)}</h3></div><span class="ability-state">${st.equipped?'Equipped':st.learned?'Learned':'Locked'}</span></div><p>${esc(a.desc||'')}</p>${requirementsView(st.requirements,a.requires)}${!st.eligible&&st.reason?`<p class="ability-reason">${esc(st.reason)}</p>`:''}${st.learned&&!st.equipped&&equipBlock?`<p class="ability-reason">${esc(equipBlock)}</p>`:''}${a.kind==='active'?`<div class="ability-meta">Cost: ${a.mp||0} mana · ${a.sp||0} stamina <span>Mastery rank ${mastery.rank||1} · ${mastery.marks||0} marks</span></div>`:''}${st.learned?(a.kind==='active'?btn(st.equipped?'ability-remove:'+id:'ability-equip:'+id,st.equipped?'Remove from active bar':'Equip ability','subtle',locked||(!st.equipped&&(!st.learned&&!st.eligible||!!activeOverflow||!!slotOverflow))):`<div class="ability-meta">Passive slot ${state.passive===id?'· Equipped':'· Select one'}</div>${btn(state.passive===id?'ability-remove:'+id:'ability-equip:'+id,state.passive===id?'Unequip passive':passiveOverflow?'Exceeds attunement':'Equip passive','subtle',locked||passiveOverflow&&state.passive!==id)}`):btn('ability-learn:'+id,st.eligible?'Learn ability':'Requirements not met','',locked||!st.eligible)}</article>`;};
 const masteryChoices=active.map(id=>{const st=G.abilityStatus(state,id)||{},m=st.mastery||{};if((m.rank||0)<3)return '';const choices=m.choices||[];return `<section class="mastery-card"><div class="flex-between"><div><span class="eyebrow">RANK 3 MASTERY</span><h3>${esc(A[id].name)}</h3></div><span class="hunt-level">${(m.rank3Choice||m.choice)?'CHOICE SET':'CHOOSE ONE'}</span></div><p>Choose the behavior that fits your build. The engine will apply the selected rank 3 effect.</p>${choices.map(c=>{const key=typeof c==='string'?c:c.id||c.key,label=typeof c==='string'?({economy:'Economy',power:'Power',barrier:'Larger barrier',recovery:'Faster recovery',immunity:'Shorter immunity',healing:'Greater healing'})[c]||c:c.name||c.label||key,desc=(m.descriptions||{})[key]||(typeof c==='string'?'':c.desc||c.description||'');return `<button data-action="mastery:${id}:${esc(key)}" class="mastery-choice ${(m.rank3Choice||m.choice)===key?'selected':''}" ${locked?'disabled':''}><strong>${esc(label)}</strong><small>${esc(desc)}</small></button>`;}).join('')}</section>`;}).join('');
 return `<div class="ability-overview"><div class="capacity-card"><strong>Attunement ${used} / 6</strong><span>${(state.equippedAbilities||[]).length} / 3 active slots · 1 passive slot</span></div><p class="muted">Learn abilities as you meet their listed requirements. Equip up to three active abilities; only equipped actions appear during combat. Rank progress comes from eligible victories.</p>${locked?'<div class="point-notice">Abilities are locked during an encounter or expedition.</div>':''}</div><section><div class="section-row"><h2>Active abilities</h2><small>Only equipped actions enter combat</small></div><div class="ability-grid">${active.map(card).join('')}</div></section><section><div class="section-row"><h2>Passive abilities</h2><small>One equipped</small></div><div class="ability-grid">${passives.map(card).join('')}</div></section>${masteryChoices?`<section><div class="section-row"><h2>Mastery choices</h2></div><div class="mastery-grid">${masteryChoices}</div></section>`:''}${Object.entries(state.mastery||{}).length?`<section class="panel mastery-progress"><div class="panel-label">MASTERY PROGRESS</div>${Object.entries(state.mastery).map(([id,m])=>`<div class="loadout-item"><div><b>${esc(A[id]?.name||id)}</b><small>${m.rank>=3?'Rank 3 · Prototype cap':`${m.marks} / ${3+2*m.rank} qualifying victories to rank ${m.rank+1}`}</small></div><span class="hunt-level">RANK ${m.rank}</span></div>`).join('')}</section>`:''}`;
}
function characterView(){const t=G.totals(state),locked=!!state.fight||!!state.delve,selected=state.gear.weapon;const tabs=`<div class="tabs sheet-tabs" role="tablist" aria-label="Character sheet">${tabButton('overview','Overview')}${tabButton('attributes',`Attributes${state.points?` · ${state.points}`:''}`)}${tabButton('abilities','Abilities')}</div>`;
 const overview=`<section class="panel"><div class="character-header"><div><div class="eyebrow">ASCENSION 0 · LEVEL ${state.level}</div><h2>${esc(state.name)}</h2><p>${esc(state.race)} · ${esc(state.origin)}</p></div>${btn('identity','Edit identity','subtle',locked)}</div><div class="xp-track"><label><span>CHARACTER EXPERIENCE</span><span>${state.level===10?'PROTOTYPE CAP':`${state.xp} / ${G.xpNeeded(state.level)} XP`}</span></label><div class="bar"><i style="width:${state.level===10?100:state.xp/G.xpNeeded(state.level)*100}%"></i></div></div></section><div class="sheet-summary"><section class="panel"><div class="panel-label">RESOURCES & DEFENSES</div><div class="stats-grid">${[['Max health',t.hp],['Max mana',t.mp],['Stamina',t.sp],['Armor',t.armor],['Ward',t.ward],['Evasion',t.evasion]].map(([n,v])=>`<div class="stat-cell"><strong>${v}</strong><small>${n.toUpperCase()}</small></div>`).join('')}</div></section>${buildPanel()}</div>${buildInspector()}`;
 const attributes=`<section class="panel"><div class="panel-label"><span>YOUR ATTRIBUTES</span><span class="gold">${state.points} POINTS AVAILABLE</span></div>${locked?'<p class="tiny muted">Attribute changes are locked during an encounter or expedition.</p>':'<p class="tiny muted">Seven attributes. Every point has an inspectable effect. Luck starts at 8; use a free respec to try a different investment.</p>'}<div class="attributes">${Object.entries(G.ATTRS).map(([k,[name,description]])=>`<div class="attribute"><span class="attr-code">${k.toUpperCase()}</span><div><b>${name}</b><span class="attribute-description">${description}</span><small>${attributeEffect(k)}</small><span class="attribute-source">Invested ${state.stats[k]} + gear ${t.gearBonuses[k]} = ${t[k]}</span></div><span class="attr-value">${t[k]}</span><button data-action="stat:${k}" aria-label="Add one point to ${name}" ${locked||state.points<=0?'disabled':''}>+</button></div>`).join('')}</div><div class="flex-between" style="margin-top:12px"><span class="tiny muted">Budget ${68+4*(state.level-1)} · Invested ${Object.values(state.stats).reduce((a,b)=>a+b,0)} · Unspent ${state.points}</span>${btn('respec','Reallocate points →','text-button tiny',locked)}</div></section><section class="panel"><div class="panel-label">PRACTICE LOADOUTS · NOT CLASSES</div><p class="tiny muted">Try an arrangement. Every attribute, item and ability stays open to you.</p><div class="kit-grid">${[['bulwark','Rod & shield','Intellect · durable casting',selected==='rod'&&state.gear.offhand==='shield'],['caster','Rod & focus','Intellect · spell output',selected==='rod'&&state.gear.offhand==='focus'],['duelist','Blade & charm','Finesse · accuracy',selected==='blade'],['breaker','Sword & shield','Might · physical pressure',selected==='sword']].map(([id,n,d,sel])=>btn('kit:'+id,`${n}<small>${d}</small>`,`kit ${sel?'selected':''}`,locked)).join('')}</div></section>`;
 return shell(`<div class="main-column character-sheet">${tabs}${charTab==='attributes'?attributes:charTab==='abilities'?abilityScreen():overview}</div>`,'A build of your own','Resources, attributes, equipment, and abilities in one readable record.','CHARACTER RECORD · BRACKEN QUAY');}
function itemStats(i){return [i.base?`${i.base} base`:null,i.armor?`${i.armor} armor`:null,i.ward?`${i.ward} ward`:null,i.spellBase?`${i.spellBase} spell base`:null,...Object.entries(i.stats||{}).map(([k,v])=>`${v} ${G.ATTRS[k]?.[0]||k}`),i.upgrade?`+${i.upgrade} upgrade`:null,i.prefix?G.PREFIXES?.[i.prefix]?.name:null,i.suffix?G.SUFFIXES?.[i.suffix]?.name:null,i.id==='seal'?'15 barrier on useful Guard':null].filter(Boolean);}
function compare(id){const i=resolved(id),choices=G.slotChoices?G.slotChoices(state,id):[i.slot],owned=state.bag.includes(id),eq=Object.values(state.gear).includes(id);const selected=choices[0]||null;const oldId=selected?state.gear[selected]:state.gear[i.slot],old=oldId?resolved(oldId):null;const slotCards=choices.length>1?`<div class="target-slot-choices"><strong>Choose a slot</strong>${choices.map(slot=>{const current=state.gear[slot]?resolved(state.gear[slot]):null;return `<button data-action="equip:${id}:${slot}" class="slot-choice" ${state.fight||state.delve?'disabled':''}><span>${SLOT_LABELS[slot]||G.SLOTS?.[slot]||slot}</span><small>Replaces ${current?.name||'Empty'}</small></button>`;}).join('')}</div>`:'';modal(i.name,`<p>${esc(i.desc)}</p><div class="compare"><div><span class="eyebrow">CURRENTLY EQUIPPED</span><h3>${esc(old?.name||'Empty slot')}</h3><p>${old?itemStats(old).map(esc).join('<br>'):'No item in this slot.'}</p></div><div><span class="eyebrow">THIS ITEM · LEVEL ${i.level}</span><h3>${esc(i.name)}</h3><p>${itemStats(i).map(esc).join('<br>')||'An authored equipment trait.'}</p></div></div>${equipmentEffectPreview(id)}<p class="modal-help">${i.channel?`Strike uses ${i.channel==='heavy'?'Might':i.channel==='precision'?'Finesse':'Intellect'} with this weapon. `:''}${i.focus?'This item enables focus-dependent spells. ':''}Equipment changes are available outside encounters and expeditions.</p><div class="modal-actions">${eq?btn('close','Keep equipped','primary'):choices.length>1?'':btn('equip:'+id+(selected?':'+selected:''),'Equip this item','primary',!owned||!!state.fight||!!state.delve||state.level<i.level)}${btn('close','Back to satchel','subtle')}</div>${choices.length>1?slotCards:''}`,'EQUIPMENT COMPARISON');}
function costLine(cost){const mats=Object.entries(cost?.materials||{}).map(([name,n])=>`${n} ${name}`).join(' + ');return [cost?.coins?`${cost.coins} coins`:null,mats||null].filter(Boolean).join(' + ')||'No cost';}
function exchangeOutput(recipe){return [...Object.entries(recipe.gain||{}).map(([name,n])=>`${n} ${name}`),...(recipe.gainItems||[]).map(id=>`1 ${resolved(id)?.name||id}`)].join(' + ')||'No listed reward';}
function costSources(cost){const mats=Object.keys(cost?.materials||{});return mats.length?mats.map(m=>`${m}: ${MATERIAL_SOURCES[m]||'Collect during hunts or use another exchange'}`).join('; '):'';}
function exchangeBlock(recipe){if(recipe.level&&state.level<recipe.level)return `Requires level ${recipe.level}.`;const owned=(recipe.gainItems||[]).find(id=>state.bag?.includes(id));return owned?`Already owned: ${resolved(owned)?.name||owned}.`:'';}
function exchangeCanAfford(recipe){return Object.entries(recipe.cost||{}).every(([m,n])=>(state.materials?.[m]||0)>=n)&&(state.coins||0)>=(recipe.coins||0);}
const MATERIAL_SOURCES={'Ledger scraps':'Rats and scavengers','Canal iron':'Scavengers and the Lockwarden','Repair fittings':'Contracts and salvage exchanges','Salvaged fittings':'Duplicate gear and workbench exchanges','Runic residue':'Wisps and the Inspector','Chainback shell':'The chainback crab','Stamped brass':'Siltbound Inspector hunts','Floodglass':'Late hunts and material exchanges','Floodglass Fragment':'The Superintendent, every clear'};
function workbenchView(){const locked=!!state.fight||!!state.delve;const items=state.bag.map(id=>resolved(id)).filter(Boolean);const exchanges=Object.values(G.EXCHANGES||{});return `<section class="workbench-intro panel"><div class="panel-label">MUNICIPAL WORKBENCH</div><h2>Make what you have go further.</h2><p>Every exchange, upgrade, and reforge shows its full cost and resulting item before anything is spent. Equipment work is unavailable during hunts and delves.</p><div class="coin-chip">${icon('coin')} ${state.coins} coins available</div>${locked?'<p class="locked-note">The workbench is closed until you return to town.</p>':''}</section><section class="workbench-section"><div class="section-row"><h2>Material exchanges</h2><small>Convert spare stock into useful parts</small></div><div class="exchange-grid">${exchanges.map(recipe=>{const blocked=exchangeBlock(recipe);return `<article class="exchange-card"><div class="eyebrow">MATERIAL EXCHANGE</div><h3>${esc(recipe.name)}</h3><div class="exchange-flow"><div><small>USES</small><strong>${Object.entries(recipe.cost||{}).map(([m,n])=>`${n} ${esc(m)}`).join(' + ')}</strong></div><span>→</span><div><small>MAKES</small><strong>${esc(exchangeOutput(recipe))}</strong></div></div><p class="material-hint">Source: ${Object.keys(recipe.cost||{}).map(m=>esc(MATERIAL_SOURCES[m]||'Hunts and contracts')).join('; ')}</p><p class="explicit-cost">Cost: ${costLine({coins:recipe.coins,materials:recipe.cost})}</p>${blocked?`<p class="ability-reason">${esc(blocked)}</p>`:''}${btn('exchange:'+recipe.id,blocked?'Unavailable · See reason':'Review exchange','subtle',locked||!!blocked)}</article>`;}).join('')}</div></section><section class="workbench-section"><div class="section-row"><h2>Upgrade or reforge gear</h2><small>Choose any item in your satchel</small></div>${items.length?`<div class="workbench-items">${items.map(i=>{const up=G.upgradePreview(state,i.id);return `<article class="workbench-item"><div><span class="eyebrow">${SLOT_LABELS[i.slot]||G.SLOTS?.[i.slot]||i.slot} ${i.upgrade?`· +${i.upgrade}`:''}</span><h3>${esc(i.name)}</h3><p>${itemStats(i).map(esc).join(' · ')||esc(i.desc)}</p></div><div class="workbench-actions">${costSources(up.cost)?`<small class="material-hint">Upgrade material: ${esc(costSources(up.cost))}</small>`:''}${btn('upgrade:'+i.id,up.level>=3?'Preview upgrade · cap reached':`Preview upgrade · ${costLine(up.cost)}`,'subtle',locked)}${['prefix','suffix'].map(kind=>{const options=Object.values(kind==='prefix'?G.PREFIXES||{}:G.SUFFIXES||{}).filter(x=>x.slots?.includes(i.slot));return options.length?btn(`affix-menu:${i.id}:${kind}`,`Reforge ${kind}`,'text-button tiny',locked):'';}).join('')}</div></article>`;}).join('')}</div>`:'<div class="empty-state">Bring equipment back from a hunt to begin upgrading and reforging it.</div>'}</section>`;}
function bagView(){const locked=!!state.fight||!!state.delve;let ids=bagTab==='shop'?Object.keys(G.ITEMS).filter(id=>resolved(id)?.price):state.bag;const slotRows=SLOT_ORDER.map(slot=>{const id=state.gear?.[slot],i=id?resolved(id):null,twoHanded=slot==='offhand'&&resolved(state.gear?.weapon)?.twoHanded;return `<div class="equipment-slot-row"><span class="slot-name">${SLOT_LABELS[slot]||G.SLOTS?.[slot]||slot}</span><div class="slot-equipped">${i?`<strong>${esc(i.name)}</strong><small>${itemStats(i).map(esc).join(' · ')||esc(i.desc)}</small>`:twoHanded?`<span class="empty-slot-label">Occupied by ${esc(resolved(state.gear.weapon).name)}</span>`:'<span class="empty-slot-label">Empty slot</span>'}</div>${i?btn('unequip-slot:'+slot,'Unequip','subtle tiny',locked||!!G.unequipReason?.(state,slot)):''}</div>`;}).join('');return shell(`<div class="layout"><div class="main-column"><div class="tabs bag-tabs">${btn('bag-tab:gear','Equipment',bagTab==='gear'?'active':'')}${btn('bag-tab:shop','Quay outfitter',bagTab==='shop'?'active':'')}${btn('bag-tab:materials','Materials',bagTab==='materials'?'active':'')}${btn('bag-tab:workbench','Workbench',bagTab==='workbench'?'active':'')}</div>${bagTab==='materials'?`<section class="panel"><h3>Materials on hand</h3>${Object.keys(state.materials||{}).length?Object.entries(state.materials).map(([n,c])=>`<div class="material-row"><span>${esc(n)}<small class="material-hint">${esc(MATERIAL_SOURCES[n]||'Collected during hunts and contracts')}</small></span><strong>${c}</strong></div>`).join(''):'<p class="muted">Complete a hunt to collect your first material.</p>'}<p class="mechanics">Materials come from specific enemies, contracts, and salvage exchanges. The workbench shows each source and spends nothing until you confirm.</p></section>`:bagTab==='workbench'?workbenchView():`<div class="inventory-summary"><span>${bagTab==='shop'?'The Quay Outfitter':'Your equipment'} · ${ids.length} items</span><span class="gold">${state.coins} coins</span></div>${locked?'<p class="tiny muted">Equipment changes and purchases are locked until the encounter or expedition ends.</p>':''}${bagTab==='gear'?`<section class="panel equipment-slots"><div class="panel-label">ALL EQUIPMENT SLOTS</div>${slotRows}</section>`:''}<div class="item-grid">${ids.map(id=>{const i=resolved(id),equipped=Object.values(state.gear).includes(id),owned=state.bag.includes(id),choices=G.slotChoices?G.slotChoices(state,id):[i.slot];return `<section class="item-card ${equipped?'equipped':''}"><div class="item-card-top"><span class="item-symbol">${icon(itemIcon(i))}</span><div><h3>${esc(i.name)}</h3><small>${SLOT_LABELS[i.slot]||G.SLOTS?.[i.slot]||i.slot} · Level ${i.level}${equipped?' · Equipped':''}${i.upgrade?` · +${i.upgrade}`:''}</small></div></div><p>${esc(i.desc)}</p><div class="item-stats">${itemStats(i).map(t=>`<span>${esc(t)}</span>`).join('')}</div>${bagTab==='shop'&&!owned?btn('buy:'+id,state.level<i.level?`Requires level ${i.level}`:`Buy · ${i.price} coins`,'',locked||state.level<i.level||state.coins<i.price):btn('compare:'+id,equipped?'Equipped · Inspect':'Compare & equip →',equipped?'subtle':'',locked||(!equipped&&(!owned||!choices.length||state.level<i.level)))}</section>`;}).join('')}</div>`}</div><aside class="side-column">${buildPanel()}${titlePanel('GOOD TO KNOW',`<h3>Build with every slot.</h3><p>Nine slots support armor, ward, attributes, and special effects. Empty slots remain available as you find or exchange for gear.</p>${btn('nav:character','Review your build →','text-button tiny')}`)}</aside></div>`,'A little better equipped','Equipment, materials, and workbench services for the build you are making.','PERSONAL EFFECTS · BRACKEN QUAY');}
function journalView(){return shell(`<div class="layout"><div class="main-column">${state.pending!==null?`<div class="point-notice">A contract outcome is ready. ${btn('claim','Review →')}</div>`:''}<div style="padding:6px 0 0 5px">${state.journal.map(j=>`<article class="journal-entry ${j.kind}"><div class="eyebrow">${{story:'A NOTE IN YOUR STORY',growth:'VISIBLE PROGRESS',achievement:'ACHIEVEMENT EARNED',discovery:'A BUILD INTERACTION'}[j.kind]||'YOUR RECORD'}</div><h3>${esc(j.title)}</h3><p>${esc(j.text)}</p></article>`).join('')}</div></div><aside class="side-column">${titlePanel(`YOUR ACHIEVEMENTS ${icon('crown')}`,state.achievements.length?state.achievements.map(a=>`<div class="achievement-card"><h4>${esc(a.title)}</h4><p>${esc(a.text)}</p></div>`).join(''):'<h3>Notable, eventually.</h3><p>Rescue someone. Stand through a heavy attack. Interrupt a bad idea. The system keeps receipts.</p>')}${questPanel()}</aside></div>`,'A record worth keeping','Your choices, discoveries, and minor administrative triumphs.','THE CHRONICLE · YOUR ADVENTURE');}
const RULES=`<section class="guide-section"><h3>One tap. One exchange.</h3><p>Choose a target, then tap Attack, Cast, Wardcast, or Defend. Your action resolves first. If the enemy survives, it responds with the displayed intent. A shared 0.65-second delay follows every accepted combat action, including the final action of a fight. Switching buttons does not bypass it. Extra taps are ignored and never queued. The timer only re-enables controls: it never attacks, restores resources, or advances the game. The game never advances combat on a timer, while closed, or without an action.</p><p>Repeating a comfortable action is fine. Tougher encounters reward reading the intent. Rest at the Quay is an immediate, explicit action outside combat. Each completed exchange restores 3 mana and 4 stamina.</p></section><section class="guide-section"><h3>Your compact action bar</h3><ul><li><strong>Attack:</strong> free weapon strike, physical damage. Sword scales with Might; blade with Finesse; rod with Intellect.</li><li><strong>Cast:</strong> Arc Bolt, 1.25× spell damage. Costs 12 mana and needs a focus-tagged item.</li><li><strong>Wardcast:</strong> 0.85× spell damage and Guard together. Costs 12 mana and 8 stamina; requires a focus and shield. This is one budgeted action.</li><li><strong>Defend:</strong> free Guard; reduces incoming damage by 35% this exchange.</li><li><strong>Recover:</strong> restore 15 mana and 20 stamina before the enemy responds.</li><li><strong>Learned active abilities:</strong> Arc Bolt costs 12 mana and begins learned. Brace costs 10 stamina; Mend 18 mana; Disrupt 14 stamina. Driving Strike, Aegis, and Expose each have their own listed costs. Their unlock requirements appear on the Abilities tab.</li><li><strong>Brace:</strong> Guard plus a barrier for this exchange. Blocks use for the next 2 exchanges. Its barrier grows with mastery.</li><li><strong>Disrupt:</strong> weapon strike. An accurate hit cancels a heavy wind-up; target then has 3 exchanges of interrupt immunity. Blocks use for the next 3 exchanges.</li><li><strong>Mend:</strong> restore health up to your maximum. Blocks use for the next 2 exchanges.</li><li><strong>Withdraw:</strong take half the enemy response, leave, and forfeit this fight’s rewards. Completed room rewards stay yours.</li></ul></section><section class="guide-section"><h3>Make a durable caster</h3><p>A new adventurer begins with Arc Bolt equipped and Prepared equipped as their passive. Reservoir unlocks at level 2 after one contract or two useful Guards; Sure Footing unlocks at level 2 after one contract. A useful Guard that prevents at least 20 hostile damage charges Reservoir. Your next Arc Bolt or Wardcast gains 10% raw spell damage. One charge maximum; it expires after the next exchange.</p><p>Try Defend or Wardcast against the rats’ Paperwork rush, then cast. The Chronicle records the first successful interaction. Unlocks are shown on the Abilities tab; learned abilities must also be equipped before their action appears in combat.</p></section><section class="guide-section"><h3>Seven attributes, one build</h3><ul>${Object.entries(G.ATTRS).map(([k,[n,d]])=>`<li><strong>${n} (${k.toUpperCase()}):</strong> ${d}.</li>`).join('')}</ul><p>Each attribute starts at a minimum of 8. The level-1 budget is 68: 56 baseline points plus 12 already invested in your starter build. Each level adds four points. A free respec returns the 12 discretionary starter points plus your level-up points. Gear bonuses are separate.</p><p>Old saves receive base Luck 8 without losing existing stats, unspent points, gear, or progress. Luck grants no extra turn, XP, or passive income.</p></section><section class="guide-section"><h3>The numbers behind the fiction</h3><p>Max HP = <code>200 + 12×level + 10×VIT + 4×WIL</code><br>Mana = <code>60 + 3×WIL + 2×INT</code><br>Stamina = <code>60 + 2×VIT + 2×FIN</code></p><p>Raw strike = <code>item base + 0.9×power + 4</code>. Power = twice the scaling attribute + level. Arc Bolt uses spell power and its mastery rank. The focus offhand adds its spell base once, to spells.</p><p>Mitigation = <code>defense / (defense + 100 + 8×attacker level)</code>, capped at 65%. Armor protects from physical damage; ward from arcane. Critical hits deal 1.25× damage. Let <code>F = max(0, LCK−8) / (max(0, LCK−8)+40)</code>. Critical chance = <code>5% + 15%×FIN/(FIN+208) + 10%×F</code>, capped at 25%. Equipment-drop chance = <code>20% + 15%×F</code>. Critical chance is checked only on a solid hit. Insight no longer reduces critical chance. Accuracy is bounded at 65–98%; failed accuracy checks are glancing hits for 55% damage, to avoid empty clicks.</p><p>Enemies’ displayed raw intent damage is reduced by your equipment, then Guard and barriers. Sure Footing adds 8 evasion rating and uses that rating in the enemy’s bounded accuracy check. Enemy glancing hits deal 55% damage. The seal’s 15 barrier applies to its triggering exchange.</p></section><section class="guide-section"><h3>Progress that belongs to you</h3><p>Level-ups grant four unallocated attribute points. Level 10 is this prototype’s cap. Free early respecs return all invested points. Equipment never changes your invested budget. Relevant equipped abilities earn at most one mastery mark each per completed eligible encounter, capped at three abilities. Mastery caps at rank 3. At rank 3, Arc Bolt chooses 9 mana or 15% more damage; Brace chooses +15 barrier or a cooldown one exchange shorter; Disrupt chooses +15% damage or one less exchange of interrupt immunity; Mend chooses +15% healing or a cooldown one exchange shorter.</p><p>Enemies 3–5 levels below you award 60% XP; 6 or more below award 25%, with no mastery. Stronger eligible hunts give up to 25% extra XP. First contract completion is awarded once.</p><p>Equipment drops start at 20%. Luck above 8 improves this chance with diminishing returns, approaching 35%. The roll chance is recorded when an encounter starts; duplicates become a salvaged fitting. The Copper-Thread Charm can drop from level 1 onward. The first boss clear gives a guaranteed item choice. Materials are collectible and used at the deterministic workbench for exchanges, gear, upgrades, and prefix/suffix reforges. Each operation shows its cost and result and asks for confirmation before spending. Random rarity tiers remain future work.</p></section><section class="guide-section"><h3>A first chapter, not a persistent world</h3><p>This is a solo, browser-local prototype based on your design pack. Progress is saved on this browser after each action. There is no account sync, multiplayer, server-verified economy, prestige, offline progress, or live AI narrator. B.U.R.S.A.R.’s responses are authored and tied to recorded events.</p><p>The source includes your modular design files. Balance, combined-action costs, enemy numbers, glancing hits and ability unlock requirements are explicit prototype choices for playtesting.</p></section>`;
function guideView(){return shell(`<div class="layout"><div class="main-column">${RULES}</div><aside class="side-column">${titlePanel('YOUR SAVE',`<h3>Keep your receipts.</h3><p>Your progress lives on this browser. Export a file to back it up or move it to another device.</p><div class="save-controls">${btn('export',`${icon('download')} Export save`,'subtle full-width')}${btn('import','Import a save','text-button full-width')}</div><p class="tiny muted" style="margin-top:16px">Save format v3. Imports v1, v2, and v3. Import replaces current local progress after confirmation.</p>`)}${titlePanel('START FRESH',`<p>Create a new local character. Export your current save first if you want to keep it.</p>${btn('reset','Start a new adventure','danger full-width')}`)}</aside></div>`,'The fine print, legibly.','Know your actions. Understand your build. Ignore the administrator’s tone.','FIELD GUIDE · RULES & SAVES');}
function syncCombatDelay(){
clearTimeout(actionDelayTimer);
const controls=$('.combat-controls');if(!controls||!state.fight)return;
const remaining=G.actionDelayRemaining(state),waiting=remaining>0;
controls.classList.toggle('waiting',waiting);
for(const button of controls.querySelectorAll('[data-action^="combat:"]')){
 const key=button.dataset.action.split(':')[1],info=G.actionInfo(state,key);
 button.disabled=waiting||!!info.reason;
 button.title=info.reason||(waiting?'Brief action delay. Tap again when ready.':info.desc);
}
$('#action-ready-text').textContent=waiting?'Brief action delay · 0.65s':'Ready for your next action';
const track=controls.querySelector('.action-delay-track i');
track.style.setProperty('--action-wait',remaining+'ms');
if(waiting)actionDelayTimer=setTimeout(syncCombatDelay,remaining+10);
}
function render(){save();$('#app').innerHTML=({hunt:huntView,character:characterView,bag:bagView,journal:journalView,guide:guideView}[view])();syncCombatDelay();}
function modal(title,body,eyebrow='ADVENTURER SERVICES'){const m=$('#modal');m.innerHTML=`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2 id="modal-title">${title}</h2></div>${btn('close','×','close')}</div><div class="modal-body">${body}</div>`;if(!m.open)m.showModal();}
function close(){if($('#modal').open)$('#modal').close();}
function claim(){if(state.pending==='bossLoot'){modal('A choice, duly earned.',`<p>The Superintendent is relieved of duty. Choose one guaranteed first-clear reward. Both can support a build; neither binds your future.</p><div class="choices">${['seal','band'].map(id=>btn('boss-loot:'+id,`<strong>${resolved(id).name}</strong><small>${resolved(id).desc}</small>`,'choice')).join('')}</div>`,'CHAPTER COMPLETE · BELOW THE WATERLINE');return;}const q=G.QUESTS[state.pending];if(!q){toast('No completed contract to turn in yet.');return;}modal(state.pending===0?'One citizen, accounted for.':q.title,`<p>${state.pending===0?'Mara stumbles out of the maintenance hatch. “You came back. Most people just file a report.” She’s safe, and she has a lead on your missing crew.':q.text}</p><p>Choose your reward. Either choice completes the contract and grants <strong>${q.xp} XP</strong>.</p><div class="choices">${btn('quest:coins','<strong>Take the payment</strong><small>20 coins for the next piece of your build.</small>','choice')}${btn('quest:materials','<strong>Help the repair crew</strong><small>10 coins + 3 repair fittings. Mara remembers the help.</small>','choice')}</div>`,'CONTRACT OUTCOME');}
function equipmentEffectPreview(id){const item=resolved(id),slot=(G.slotChoices?.(state,id)||[item.slot]).find(x=>!state.gear[x])||(G.slotChoices?.(state,id)||[item.slot])[0];if(!slot)return '';const before=G.totals(state),gear={...state.gear,[slot]:id};for(const [k,v] of Object.entries(gear))if(k!==slot&&v===id)gear[k]=null;if(item.twoHanded)gear.offhand=null;const after=G.totals({...state,gear});const names={hp:'Max health',mp:'Max mana',sp:'Max stamina',armor:'Armor',ward:'Ward',heavyPower:'Heavy power',precisionPower:'Precision power',spellPower:'Spell power',physicalAcc:'Physical accuracy',spellAcc:'Spell accuracy',evasion:'Evasion',critChance:'Critical chance',equipmentDropChance:'Equipment drops'};const changes=Object.entries(names).filter(([key])=>before[key]!==after[key]);return changes.length?`<h3>What changes for your build</h3><div class="equipment-effects">${changes.map(([key,name])=>`<p><strong>${name}</strong><br>${['critChance','equipmentDropChance'].includes(key)?percent(before[key]):before[key]} → ${['critChance','equipmentDropChance'].includes(key)?percent(after[key]):after[key]}</p>`).join('')}</div>`:'';}
function costLedger(cost){const rows=[];if(cost?.coins)rows.push(`Coins: ${state.coins} / ${cost.coins}`);for(const [m,n] of Object.entries(cost?.materials||{}))rows.push(`${m}: ${state.materials?.[m]||0} / ${n}`);return rows.length?`<p class="cost-ledger">On hand · ${rows.map(esc).join(' · ')}</p>`:'';}
function bonusLabels(bonus={}){return [...Object.entries(bonus).filter(([k])=>k!=='stats').map(([k,v])=>`${v} ${k}`),...Object.entries(bonus.stats||{}).map(([k,v])=>`${v} ${G.ATTRS[k]?.[0]||k}`)].join(' · ')||'No listed bonus';}
function previewPair(title,p,confirmAction,eyebrow='WORKBENCH PREVIEW'){const before=p?.before,after=p?.after,price=costLine(p?.cost);modal(title,`<p class="explicit-cost"><strong>Cost to confirm: ${esc(price)}</strong></p>${costLedger(p?.cost)}${costSources(p?.cost)?`<p class="material-hint">Source: ${esc(costSources(p.cost))}</p>`:''}<div class="compare"><div><span class="eyebrow">BEFORE</span><h3>${esc(before?.name||'Current item')}</h3><p>${itemStats(before||{}).map(esc).join('<br>')||'No listed bonuses.'}</p></div><div><span class="eyebrow">AFTER</span><h3>${esc(after?.name||'Updated item')}</h3><p>${itemStats(after||{}).map(esc).join('<br>')||'No listed bonuses.'}</p></div></div>${p?.reason?`<p class="ability-reason">${esc(p.reason)}</p>`:''}<p class="modal-help">No currency or materials are spent until you confirm below.</p><div class="modal-actions">${btn(confirmAction,'Confirm and spend','primary',!p?.allowed||!!state.fight||!!state.delve)}${btn('close','Cancel','subtle')}</div>`,eyebrow);}
function openExchange(id){const r=G.EXCHANGES?.[id];if(!r)return;const block=exchangeBlock(r),can=exchangeCanAfford(r);modal(r.name,`<div class="exchange-flow"><div><small>YOU GIVE</small><strong>${Object.entries(r.cost||{}).map(([m,n])=>`${n} ${esc(m)}`).join(' + ')}</strong></div><span>→</span><div><small>YOU RECEIVE</small><strong>${esc(exchangeOutput(r))}</strong></div></div><p>Source: ${Object.keys(r.cost||{}).map(m=>esc(MATERIAL_SOURCES[m]||'Hunts and contracts')).join('; ')}</p>${block?`<p class="ability-reason">${esc(block)}</p>`:''}<p class="explicit-cost"><strong>Cost: ${costLine({coins:r.coins,materials:r.cost})}</strong></p>${costLedger({coins:r.coins,materials:r.cost})}<div class="modal-actions">${btn('exchange-confirm:'+id,'Confirm exchange','primary',!can||!!block||!!state.fight||!!state.delve)}${btn('close','Cancel','subtle')}</div>`,'MATERIAL EXCHANGE');}
function openAffixMenu(id,kind){const item=resolved(id),list=kind==='prefix'?G.PREFIXES:G.SUFFIXES;const candidates=Object.values(list||{}).filter(x=>x.slots?.includes(item.slot));modal(`Reforge ${item.name}`,`<p>Choose a ${kind} to preview. An existing ${kind} will be replaced only after you confirm the new cost.</p><div class="affix-options">${candidates.map(x=>{const p=G.affixPreview(state,id,kind,x.id);return `<button data-action="affix-preview:${id}:${kind}:${x.id}" class="affix-option" ${!!state.fight||!!state.delve?'disabled':''}><strong>${esc(x.name)}</strong><small>${bonusLabels(x.bonus)}</small><small>Cost: ${costLine(p.cost)}</small>${costSources(p.cost)?`<small>Source: ${esc(costSources(p.cost))}</small>`:''}${p.reason?`<small>${esc(p.reason)}</small>`:''}</button>`;}).join('')}</div><div class="modal-actions">${btn('close','Back','subtle')}</div>`,'CHOOSE A REFORGE');}
function exportSave(){const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`crown-calamity-level-${state.level}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save exported. Keep it somewhere dry.');}
function identity(){modal('Your name on the paperwork.',`<label>Adventurer name<input id="name-input" maxlength="32" value="${esc(state.name)}" autocomplete="off"></label><label>Race<select id="race-input"><option ${state.race==='Human'?'selected':''}>Human</option><option ${state.race==='Stonekin'?'selected':''}>Stonekin</option></select></label><label>Background<input id="origin-input" maxlength="70" value="${esc(state.origin)}"></label><p class="modal-help">Both races share the same attribute budget and ability access. Identity has no portrait.</p><div class="modal-actions">${btn('save-identity','Save identity','primary')}${btn('close','Cancel','subtle')}</div>`);}
async function act(action){const parts=action.split(':'),[a,b,c]=parts,d=parts.slice(3).join(':');if(a==='close'){close();return;}if(a==='char-tab'){charTab=b;render();window.scrollTo({top:0});return;}if(a==='nav'){view=b;render();window.scrollTo({top:0});return;}if(a==='rest'){if(G.restore(state)){render();toast('Recovered fully at Bracken Quay. No time, coin, or progress required.');}else toast('Recovery at the Quay is available outside combat and expeditions.');return;}
if(a==='hunt'){if(state.delve){toast('Finish or leave the delve before hunting.');return;}if(G.startFight(state,b)){view='hunt';huntTab='hunts';render();window.scrollTo({top:0});}else toast(state.hp<=0?'Recover at the Quay before setting out.':'This hunt is not available yet.');return;}
if(a==='combat'){const before=state.discoveries.length;const result=G.exchange(state,b);if(!result.ok){toast(result.reason);return;}render();if(state.discoveries.length>before)toast('Interaction discovered: Stored Pressure. Recorded in your Chronicle.');if(result.victory||result.defeat||result.withdraw)window.scrollTo({top:0});return;}
if(a==='toggle-log'){state.settings.details=!state.settings.details;render();return;}if(a==='mechanics'){modal('Every action, accounted for.',`<p>Attack is free. Cast spends 12 mana. Wardcast trades spell damage for Guard (12 mana, 8 stamina). Defend is free. Each tap resolves just this exchange. A shared 0.65-second delay follows accepted actions. Extra taps during that pause are ignored, not queued.</p><p>Recover restores 15 mana / 20 stamina; the enemy still acts. Brace, Disrupt, and Mend show remaining cooldown exchanges on their buttons. A blocked action spends no turn.</p><p>Reservoir needs Guard to prevent at least 20 damage. It stores one +10% spell charge for the next exchange only.</p><div class="modal-actions">${btn('close','Back to the encounter','primary')}${btn('open-guide','All the rules →','subtle')}</div>`,'COMBAT REFERENCE');return;}
if(a==='open-guide'){close();view='guide';render();window.scrollTo({top:0});return;}if(a==='tab'){huntTab=b;state.last=null;render();return;}if(a==='clear-outcome'){state.last=null;render();return;}if(a==='delve-show'){state.last=null;huntTab='delve';render();return;}if(a==='delve-start'){if(G.startDelve(state)){huntTab='delve';render();}return;}if(a==='delve'){if(G.delveAction(state,b)){state.last=null;render();window.scrollTo({top:0});if(b==='rest')toast('Camp used. Resources fully restored.');}return;}if(a==='delve-leave'){modal('Return to town?',`<p>Your completed room rewards stay yours. This run ends, and its camp and rooms reset on your next entry.</p><div class="modal-actions">${btn('confirm-leave','Return to the Quay','primary')}${btn('close','Stay in the works','subtle')}</div>`);return;}if(a==='confirm-leave'){G.delveAction(state,'leave');close();render();return;}
if(a==='claim'){claim();return;}if(a==='quest'){if(G.completeQuest(state,b)){close();render();toast('Contract completed. Rewards and your choice recorded.');}return;}if(a==='boss-loot'){if(G.chooseBossLoot(state,b)){close();render();toast(`${resolved(b).name} added to your satchel.`);}return;}
if(a==='stat'){if(G.allocate(state,b)){render();}return;}if(a==='kit'){if(G.practice(state,b)){render();toast('Practice loadout equipped. This is a starting point, not a class.');}return;}if(a==='passive'){if(G.equipAbility(state,b)){render();toast('Passive equipped.');}else toast(G.abilityStatus(state,b)?.reason||'Passive cannot be equipped.');return;}
if(a==='ability-learn'){if(G.learnAbility(state,b)){render();toast(`${G.ABILITIES[b].name} learned.`);}else toast(G.abilityStatus(state,b)?.reason||'Requirements are not met.');return;}if(a==='ability-equip'){if(G.equipAbility(state,b)){render();toast(`${G.ABILITIES[b].name} equipped.`);}else toast(G.abilityStatus(state,b)?.reason||'Ability cannot be equipped.');return;}if(a==='ability-remove'){if(G.unequipAbility(state,b)){render();toast(G.ABILITIES[b].kind==='passive'?`${G.ABILITIES[b].name} removed from the passive slot.`:`${G.ABILITIES[b].name} removed from the active bar.`);}return;}if(a==='mastery'){if(G.chooseMastery(state,b,c)){render();toast('Mastery choice recorded.');}return;}if(a==='identity'){identity();return;}if(a==='save-identity'){if(state.fight||state.delve)return;const n=$('#name-input').value.trim();if(!n){$('#name-input').focus();toast('Your name cannot be blank.');return;}state.name=n.slice(0,32);state.race=$('#race-input').value;state.origin=$('#origin-input').value.trim().slice(0,70)||'Adventurer of Bracken Quay';close();render();return;}
if(a==='respec'){modal('Reconsider your unreasonable choices.',`<p>Return all invested attributes to 8 and reclaim ${12+4*(state.level-1)} points to allocate. Equipment and learned mastery stay yours. Current resources will be capped to your revised limits.</p><div class="modal-actions">${btn('confirm-respec','Reallocate for free','primary')}${btn('close','Keep this build','subtle')}</div>`,'FREE EARLY RESPEC');return;}if(a==='confirm-respec'){if(G.resetStats(state)){close();render();}return;}
if(a==='shop-luck'){view='bag';bagTab='shop';render();window.scrollTo({top:0});return;}if(a==='bag-tab'){bagTab=b;render();return;}if(a==='compare'){compare(b);return;}if(a==='equip'){if(G.equip(state,b,c)){close();render();toast(`${resolved(b).name} equipped in ${SLOT_LABELS[c||resolved(b).slot]||c||resolved(b).slot}.`);}return;}if(a==='unequip-slot'){if(G.unequip(state,b)){render();toast(`${SLOT_LABELS[b]||b} slot emptied.`);}return;}if(a==='exchange'){openExchange(b);return;}if(a==='exchange-confirm'){const r=G.exchangeMaterials(state,b);if(r){close();render();toast(r.gainedItems?.length?`${r.gainedItems.map(id=>resolved(id)?.name||id).join(', ')} added to your satchel.`:'Materials exchanged. The receipt is in your satchel.');}else toast('Exchange unavailable: check the listed materials and coins.');return;}if(a==='upgrade'){const p=G.upgradePreview(state,b);previewPair(`Upgrade ${resolved(b).name}`,p,'upgrade-confirm:'+b);return;}if(a==='upgrade-confirm'){if(G.upgradeItem(state,b)){close();render();toast(`${resolved(b).name} upgraded.`);}return;}if(a==='affix-menu'){openAffixMenu(b,c);return;}if(a==='affix-preview'){const p=G.affixPreview(state,b,c,d);previewPair(`Apply ${G[c==='prefix'?'PREFIXES':'SUFFIXES']?.[d]?.name||'affix'}`,p,`affix-confirm:${b}:${c}:${d}`,'REFORGE PREVIEW');return;}if(a==='affix-confirm'){if(G.applyAffix(state,b,c,d)){close();render();toast(`${resolved(b).name} reforged.`);}return;}if(a==='buy'){if(G.buy(state,b)){render();toast(`${resolved(b).name} added to your satchel. Compare it before equipping.`);}return;}
if(a==='export'){exportSave();return;}if(a==='import'){modal('Bring your adventure with you.',`<p>Importing replaces this browser’s current adventure. Export your current save first if you want to keep it.</p><input id="save-file" class="file-input" type="file" accept="application/json,.json" aria-label="Choose save file"><div class="modal-actions">${btn('confirm-import','Import and replace','primary')}${btn('close','Cancel','subtle')}</div>`,'SAVE MANAGEMENT');return;}
if(a==='confirm-import'){const f=$('#save-file').files[0];if(!f){toast('Choose a save file first.');return;}if(f.size>2e6){toast('That file is too large to be a save.');return;}const parsed=G.loadSave(await f.text());if(!parsed){toast('This is not a supported Crown & Calamity save.');return;}state=parsed;close();view='hunt';huntTab=state.delve?'delve':'hunts';render();toast('Adventure imported.');return;}
if(a==='reset'){modal('A new name on the ledger.',`<p>This replaces your current local adventure with a fresh level 1 character. Export a save first to keep this one.</p><div class="modal-actions">${btn('confirm-reset','Start a new adventure','danger')}${btn('close','Keep this adventure','subtle')}</div>`);return;}if(a==='confirm-reset'){state=G.fresh();view='hunt';huntTab='hunts';close();render();window.scrollTo({top:0});return;}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){try{Promise.resolve(act(b.dataset.action)).catch(err=>{console.error(err);toast('That action could not be completed. Your last saved progress is safe.');});}catch(err){console.error(err);toast('That action could not be completed.');}}});
document.addEventListener('keydown',e=>{if(e.repeat&&e.target.closest('[data-action^="combat:"]'))e.preventDefault();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
document.addEventListener('change',e=>{if(e.target.id==='inspect-target'&&G.ENEMIES.some(x=>x.id===e.target.value)){state.settings.inspectTarget=e.target.value;render();$('#inspect-target')?.focus();}});
if(state.delve)huntTab='delve';render();
